import { useCallback } from 'react';
import {
  ReactFlow,
  ReactFlowProvider,  // 👈 Import ReactFlowProvider
  addEdge,
  useNodesState,
  useEdgesState,
  Background,
  Controls,
  MiniMap,
  useReactFlow
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import FiberDeviceNode from './FiberDeviceNode';

const nodeTypes = { fiberDevice: FiberDeviceNode };

// 👇 Inner component that uses useReactFlow hook
function FlowContent({ onElementSelect, nodes, setNodes, edges, setEdges }) {
  const { screenToFlowPosition } = useReactFlow();

  const onConnect = useCallback(
    (params) => {
      const newEdge = {
        ...params,
        id: `edge-${params.source}-${params.target}-${Date.now()}`,
        label: 'Fiber Link',
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 },
        labelStyle: { fill: '#334155', fontWeight: 500, fontSize: '11px' },
        labelShowBg: true,
        labelBgStyle: { fill: '#fff', stroke: '#cbd5e1' },
        labelBgPadding: [4, 4]
      };
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [setEdges]
  );

  const onDragOver = useCallback((event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event) => {
      event.preventDefault();
      const type = event.dataTransfer.getData('application/reactflow');
      if (!type) return;

      const position = screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });

      const newNode = {
        id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        type: 'fiberDevice',
        position,
        data: { type, hostname: '', ip: '' },
      };
      setNodes((nds) => [...nds, newNode]);
    },
    [screenToFlowPosition, setNodes]
  );

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={() => {}}
      onEdgesChange={() => {}}
      onConnect={onConnect}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onNodeClick={(_, node) => onElementSelect({ type: 'node', id: node.id })}
      onEdgeClick={(_, edge) => onElementSelect({ type: 'edge', id: edge.id })}
      onPaneClick={() => onElementSelect(null)}
      nodeTypes={nodeTypes}
      fitView
      fitViewOptions={{ padding: 0.2 }}
      className="react-flow-container"
      minZoom={0.2}
      maxZoom={2}
    >
      <Background color="#e2e8f0" gap={24} size={1} />
      <Controls showInteractive={false} />
      <MiniMap 
        nodeColor={(node) => {
          const colors = { router: '#ef4444', switch: '#f59e0b', olt: '#10b981', ont: '#3b82f6' };
          return colors[node.data?.type] || '#64748b';
        }}
        maskColor="rgba(241, 245, 249, 0.85)"
      />
    </ReactFlow>
  );
}

// 👇 Main exported component with Provider wrapper
export default function NetworkFlow(props) {
  return (
    <ReactFlowProvider>
      <FlowContent {...props} />
    </ReactFlowProvider>
  );
}
